package com.kuzhi.findme.client;

import java.util.HashMap;
import java.util.Map;

public final class FindMePreviewInteractionState {
    private static final Map<String, MutableView> VIEWS = new HashMap<String, MutableView>();

    private FindMePreviewInteractionState() {
    }

    public static View view(String id) {
        MutableView view = VIEWS.computeIfAbsent(FindMePreviewInteractionState.normalize(id), ignored -> new MutableView());
        return new View(view.yaw, view.pitch, view.zoom, view.offsetX, view.offsetY);
    }

    public static void rotate(String id, double deltaX, double deltaY) {
        MutableView view = VIEWS.computeIfAbsent(FindMePreviewInteractionState.normalize(id), ignored -> new MutableView());
        view.yaw = FindMePreviewInteractionState.wrap(view.yaw + (float)deltaX * 0.75f);
        view.pitch = FindMePreviewInteractionState.clamp(view.pitch + (float)deltaY * 0.55f, -35.0f, 35.0f);
    }

    public static void pan(String id, double deltaX, double deltaY) {
        MutableView view = VIEWS.computeIfAbsent(FindMePreviewInteractionState.normalize(id), ignored -> new MutableView());
        view.offsetX = FindMePreviewInteractionState.clamp(view.offsetX + (float)deltaX, -80.0f, 80.0f);
        view.offsetY = FindMePreviewInteractionState.clamp(view.offsetY + (float)deltaY, -80.0f, 80.0f);
    }

    public static void zoom(String id, double wheelDelta) {
        MutableView view = VIEWS.computeIfAbsent(FindMePreviewInteractionState.normalize(id), ignored -> new MutableView());
        float factor = wheelDelta > 0.0 ? 0.9f : 1.1f;
        view.zoom = FindMePreviewInteractionState.clamp(view.zoom * factor, 0.35f, 3.0f);
    }

    private static String normalize(String id) {
        return id == null || id.isBlank() ? "default" : id;
    }

    private static float wrap(float value) {
        float wrapped = value % 360.0f;
        return wrapped < 0.0f ? wrapped + 360.0f : wrapped;
    }

    private static float clamp(float value, float minimum, float maximum) {
        return Math.max(minimum, Math.min(maximum, value));
    }

    private static final class MutableView {
        private float yaw = 180.0f;
        private float pitch;
        private float zoom = 1.0f;
        private float offsetX;
        private float offsetY;

        private MutableView() {
        }
    }

    public record View(float yaw, float pitch, float zoom, float offsetX, float offsetY) {
    }
}

