    public static final RegistryObject<Item> VEHICLE_BINDER = ITEMS.register("vehicle_binder", () -> new VehicleBinderItem(new Item.Properties().m_41487_(16)));
    public static final RegistryObject<Item> NAME_PAPER = ITEMS.register("name_paper", () -> new NamePaperItem(new Item.Properties().m_41487_(16)));
    public static final RegistryObject<SmallHouseItem> SMALL_HOUSE = ITEMS.register("small_house", () -> new SmallHouseItem((Block)ModBlocks.SMALL_HOUSE.get(), new Item.Properties()));

    private ModItems() {
    }

    public static void register(IEventBus bus) {
        ITEMS.register(bus);
    }

    public static void addCreative(BuildCreativeModeTabContentsEvent event) {
        if (event.getTabKey().equals(FindMeCreativeTabs.MAIN)) {
            if (Config.moduleConfigured(FindMeModule.RIDING) && !ExternalVehicleBridge.available()) {
                event.m_246326_((ItemLike)VEHICLE_BINDER.get());
            }
            if (Config.moduleConfigured(FindMeModule.RIDING) || Config.moduleConfigured(FindMeModule.COMPANIONS)) {
                event.m_246326_((ItemLike)NAME_PAPER.get());
            }
            if (Config.moduleConfigured(FindMeModule.HOUSES) && Config.moduleConfigured(FindMeModule.COMPANIONS)) {
                event.m_246326_((ItemLike)SMALL_HOUSE.get());
            }
        }
    }
}

